     1	use super::{
     2	    AUTOMATIC_THRESHOLD, AddressMatchQuality, BTreeMap, BTreeSet, EntityIngestionError,
     3	    FunderObservationId, FunderRole, IdentityBasis, Observation, ObservationResolution,
     4	    PairDecision, PairDisposition, PairReason, ResolutionInput, ScoredPair, ScoringInput, invalid,
     5	};
     6	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
     7	enum EntityKind {
     8	    Person,
     9	    Organisation,
    10	    Unknown,
    11	}
    12	fn kind(observation: &Observation) -> EntityKind {
    13	    match observation
    14	        .donor_kind
    15	        .as_deref()
    16	        .map(str::trim)
    17	        .map(str::to_ascii_lowercase)
    18	        .as_deref()
    19	    {
    20	        Some("individual" | "person") => EntityKind::Person,
    21	        Some(
    22	            "company"
    23	            | "charity"
    24	            | "trade union"
    25	            | "union"
    26	            | "other organisation"
    27	            | "organisation"
    28	            | "unincorporated association"
    29	            | "registered party"
    30	            | "trust"
    31	            | "limited liability partnership"
    32	            | "friendly society"
    33	            | "building society",
    34	        ) => EntityKind::Organisation,
    35	        _ => EntityKind::Unknown,
    36	    }
    37	}
    38	pub(super) fn company(observation: &Observation) -> Option<String> {
    39	    if observation
    40	        .donor_kind
    41	        .as_deref()
    42	        .is_some_and(|kind| !kind.trim().eq_ignore_ascii_case("company"))
    43	    {
    44	        return None;
    45	    }
    46	    let number = observation
    47	        .donor_company_number
    48	        .as_ref()?
    49	        .trim_matches(|c: char| c.is_ascii_whitespace())
    50	        .to_ascii_uppercase();
    51	    (number.len() == 8
    52	        && number.bytes().all(|b| b.is_ascii_alphanumeric())
    53	        && number.bytes().any(|b| b.is_ascii_digit()))
    54	    .then_some(number)
    55	}
    56	
    57	#[derive(Clone, Copy)]
    58	enum LinkEvidence {
    59	    Statistical,
    60	    DonorName,
    61	    ExtractedName,
    62	    TradeUnionFamily,
    63	}
    64	#[derive(Clone, Copy)]
    65	enum EdgeEligibility {
    66	    Link(LinkEvidence),
    67	    Review,
    68	    Reject(PairReason),
    69	}
    70	struct CandidateEdge {
    71	    decision: PairDecision,
    72	    eligibility: EdgeEligibility,
    73	}
    74	fn classify(a: &Observation, b: &Observation, probability: f64) -> EdgeEligibility {
    75	    if kind(a) != EntityKind::Unknown && kind(b) != EntityKind::Unknown && kind(a) != kind(b) {
    76	        return EdgeEligibility::Reject(PairReason::PersonOrganisationConflict);
    77	    }
    78	    let exact_name = a.name_normalized.is_some() && a.name_normalized == b.name_normalized;
    79	    let full_addresses = a.address_match_quality == AddressMatchQuality::NumberedStreet
    80	        && b.address_match_quality == AddressMatchQuality::NumberedStreet
    81	        && a.address_normalized.is_some()
    82	        && b.address_normalized.is_some();
    83	    let addresses_agree = a
    84	        .address_normalized
    85	        .as_deref()
    86	        .zip(b.address_normalized.as_deref())
    87	        .is_some_and(|(left, right)| address_key(left) == address_key(right));
    88	    let same_union_family = trade_union(a)
    89	        && trade_union(b)
    90	        && union_root(a.name_raw.as_deref()).is_some()
    91	        && union_root(a.name_raw.as_deref()) == union_root(b.name_raw.as_deref());
    92	    let extracted_name_agrees = aliases_agree(a, b)
    93	        || (organization_compatible(a, b)
    94	            && addresses_agree
    95	            && representative_annotation(a, b)
    96	            && base_name_overlap(a, b));
    97	    if same_union_family {
    98	        EdgeEligibility::Link(LinkEvidence::TradeUnionFamily)
    99	    } else if exact_name && full_addresses && addresses_agree && probability >= AUTOMATIC_THRESHOLD
   100	    {
   101	        EdgeEligibility::Link(LinkEvidence::Statistical)
   102	    } else if exact_name && a.role == FunderRole::Donor && b.role == FunderRole::Donor {
   103	        EdgeEligibility::Link(LinkEvidence::DonorName)
   104	    } else if extracted_name_agrees {
   105	        EdgeEligibility::Link(LinkEvidence::ExtractedName)
   106	    } else if full_addresses && !addresses_agree {
   107	        EdgeEligibility::Reject(PairReason::FullAddressDisagreement)
   108	    } else {
   109	        EdgeEligibility::Review
   110	    }
   111	}
   112	
   113	fn trade_union(observation: &Observation) -> bool {
   114	    observation
   115	        .donor_kind
   116	        .as_deref()
   117	        .is_some_and(|kind| kind.trim().eq_ignore_ascii_case("trade union"))
   118	}
   119	fn organization_compatible(a: &Observation, b: &Observation) -> bool {
   120	    let left = kind(a);
   121	    let right = kind(b);
   122	    !matches!(left, EntityKind::Person)
   123	        && !matches!(right, EntityKind::Person)
   124	        && (matches!(left, EntityKind::Organisation) || matches!(right, EntityKind::Organisation))
   125	}
   126	fn union_root(raw: Option<&str>) -> Option<&'static str> {
   127	    let raw = raw?.to_lowercase();
   128	    raw.split(|c: char| !c.is_alphanumeric())
   129	        .any(|word| word == "unite")
   130	        .then_some("unite")
   131	}
   132	fn aliases_agree(a: &Observation, b: &Observation) -> bool {
   133	    a.alias_normalized.iter().any(|alias| {
   134	        b.alias_normalized.iter().any(|other| alias == other)
   135	            || b.name_normalized.as_ref() == Some(alias)
   136	    }) || b
   137	        .alias_normalized
   138	        .iter()
   139	        .any(|alias| a.name_normalized.as_ref() == Some(alias))
   140	}
   141	fn address_key(value: &str) -> String {
   142	    value
   143	        .chars()
   144	        .flat_map(char::to_lowercase)
   145	        .map(|c| if c.is_alphanumeric() { c } else { ' ' })
   146	        .collect::<String>()
   147	        .split_whitespace()
   148	        .collect::<Vec<_>>()
   149	        .join(" ")
   150	}
   151	fn representative_annotation(a: &Observation, b: &Observation) -> bool {
   152	    [a, b].iter().any(|observation| {
   153	        let Some(qualifier) = observation
   154	            .name_raw
   155	            .as_deref()
   156	            .and_then(|name| name.split_once('(').map(|(_, qualifier)| qualifier))
   157	        else {
   158	            return false;
   159	        };
   160	        let words = qualifier
